51	        instances.put(type, instance);
52	        return this;
53	    }
54	
55	    @SuppressWarnings("unchecked")
56	    <T> T get(Class<T> type) {
57	        Object existing = instances.get(type);
58	        if (existing != null) {
59	            return (T) existing;
60	        }
61	        if (type == String.class) {
62	            return (T) "";
63	        }
64	        if (type.isPrimitive()) {
65	            return (T) defaultPrimitive(type);
66	        }
67	        Object bean = ctx.getBeanProvider(type).getIfUnique();
68	        if (bean != null) {
69	            return (T) bean;
70	        }
71	        Object created;
72	        if (isDomainComponent(type) && !building.contains(type)) {
73	            building.add(type);
74	            try {
75	                created = construct(type);
76	            } finally {
77	                building.remove(type);
78	            }
79	        } else {
80	            created = Mockito.mock(type);
81	        }
82	        instances.put(type, created);
83	        return (T) created;
84	    }
85	
86	    private static boolean isDomainComponent(Class<?> t) {
87	        return t.getName().startsWith(DOMAIN + ".")
88	                && !t.isInterface()
89	                && !Modifier.isAbstract(t.getModifiers())
90	                && org.springframework.core.annotation.AnnotatedElementUtils.hasAnnotation(t, Component.class);
91	    }
92	
93	    private Object construct(Class<?> type) {
94	        try {
95	            Constructor<?> ctor = null;
96	            for (Constructor<?> c : type.getDeclaredConstructors()) {
97	                if (c.isAnnotationPresent(Autowired.class)) {
98	                    ctor = c;
99	                }
100	            }
101	            if (ctor == null) {
102	                ctor = java.util.Arrays.stream(type.getDeclaredConstructors())
103	                        .max(Comparator.comparingInt(Constructor::getParameterCount))
104	                        .orElseThrow();
105	            }
106	            Class<?>[] params = ctor.getParameterTypes();
107	            Object[] args = new Object[params.length];
108	            for (int i = 0; i < params.length; i++) {
109	                args[i] = get(params[i]);
110	            }
111	            ctor.setAccessible(true);
112	            Object obj = ctor.newInstance(args);
113	            instances.put(type, obj);
114	            for (Class<?> c = type; c != null && c != Object.class; c = c.getSuperclass()) {
115	                for (Field f : c.getDeclaredFields()) {
116	                    if (f.isAnnotationPresent(Autowired.class) && !Modifier.isStatic(f.getModifiers())) {
117	                        f.setAccessible(true);
118	                        if (f.get(obj) == null) {
119	                            f.set(obj, get(f.getType()));
120	                        }
121	                    }
122	                }
123	            }
124	            return obj;
125	        } catch (ReflectiveOperationException e) {
126	            throw new IllegalStateException("cannot build " + type.getName(), e);
127	        }
128	    }
129	
130	    private void dispatch(Object event) {
131	        Object payload = (event instanceof PayloadApplicationEvent<?> p) ? p.getPayload() : event;
132	        for (Class<?> listenerType : listenerClasses()) {
133	            for (Method m : listenerType.getDeclaredMethods()) {
134	                boolean listener = m.isAnnotationPresent(EventListener.class)
135	                        || m.isAnnotationPresent(TransactionalEventListener.class);
136	                if (!listener || m.getParameterCount() != 1) {
137	                    continue;
138	                }
139	                Class<?> p = m.getParameterTypes()[0];
140	                Object arg = p.isInstance(payload) ? payload
141	                        : (event instanceof ApplicationEvent && p.isInstance(event)) ? event : null;
142	                if (arg == null) {
143	                    continue;
144	                }
145	                try {
146	                    m.setAccessible(true);
147	                    m.invoke(get(listenerType), arg);
148	                } catch (InvocationTargetException e) {
149	                    Throwable t = e.getTargetException();
150	                    if (t instanceof RuntimeException re) {
151	                        throw re;
152	                    }
153	                    throw new IllegalStateException(t);
154	                } catch (IllegalAccessException e) {
155	                    throw new IllegalStateException(e);
156	                }
157	            }
158	        }
159	    }
