package com.fream.back.domain.user.entity;

import com.fream.back.global.entity.BaseTimeEntity;
import jakarta.persistence.*;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Getter;
import lombok.NoArgsConstructor;

import java.time.LocalDate;

@Entity
@Getter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class Point extends BaseTimeEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "user_id")
    private User user; // 포인트 소유 사용자

    private int amount; // 초기 포인트 금액

    private int remainingAmount; // 남은 포인트 금액

    private String reason; // 포인트 적립/사용 이유

    private LocalDate expirationDate; // 포인트 유효기간

    @Enumerated(EnumType.STRING)
    private PointStatus status; // 포인트 상태 (사용가능/사용완료/포인트소멸)

    // 기본 생성자 업데이트
    public Point(User user, int amount, String reason) {
        this.user = user;
        this.amount = amount;
        this.remainingAmount = amount; // 초기 남은 금액은 전체 금액
        this.reason = reason;
        this.expirationDate = LocalDate.now().plusDays(90); // 생성 시점부터 90일 후
        this.status = PointStatus.AVAILABLE; // 기본 상태는 사용가능
    }

    // 편의 메서드
    public void assignUser(User user) {
        this.user = user;
    }

    public void unassignUser() {
        this.user = null;
    }

    // 포인트 사용 메서드
    public int use(int amountToUse) {
        if (this.status != PointStatus.AVAILABLE) {
            return 0; // 사용 불가능한 포인트는 0 반환
        }

        if (amountToUse >= this.remainingAmount) {
            int used = this.remainingAmount;
            this.remainingAmount = 0;
            this.status = PointStatus.USED; // 전부 사용 완료
            return used;
        } else {
            this.remainingAmount -= amountToUse;
            return amountToUse;
        }
    }

    // 포인트 소멸 처리 메서드
    public void expire() {
        if (this.status == PointStatus.AVAILABLE) {
            this.status = PointStatus.EXPIRED;
            this.remainingAmount = 0;
        }
    }

    // 포인트 사용 이유 설정
    public void setReason(String reason) {
        this.reason = reason;
    }

    // 포인트 유효성 체크
    public boolean isValid() {
        return this.status == PointStatus.AVAILABLE &&
                expirationDate.isAfter(LocalDate.now());
    }
    /**
     * 포인트 만료일 설정
     */
    public void setExpirationDate(LocalDate expirationDate) {
        this.expirationDate = expirationDate;
    }

    /**
     * 포인트 상태 설정
     */
    public void setStatus(PointStatus status) {
        this.status = status;
    }
}package com.fream.back.domain.user.service.point;

import com.fream.back.domain.user.dto.PointDto;
import com.fream.back.domain.user.entity.Point;
import com.fream.back.domain.user.entity.PointStatus;
import com.fream.back.domain.user.entity.User;
import com.fream.back.domain.user.exception.InsufficientPointsException;
import com.fream.back.domain.user.exception.InvalidPointAmountException;
import com.fream.back.domain.user.exception.UserNotFoundException;
import com.fream.back.domain.user.repository.PointRepository;
import com.fream.back.domain.user.service.query.UserQueryService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDate;
import java.util.List;

@Slf4j
@Service
@RequiredArgsConstructor
public class PointCommandService {

    private final PointRepository pointRepository;
    private final UserQueryService userQueryService;

    /**
     * 포인트 적립
     */
    @Transactional
    public PointDto.PointResponse addPoint(String email, PointDto.AddPointRequest request) {
        log.info("포인트 적립 시작 - 사용자: {}, 적립액: {}", email, request.getAmount());

        try {
            // 입력값 검증
            validateAddPointRequest(request);

            User user = userQueryService.findByEmail(email);
            if (user == null) {
                throw new UserNotFoundException(email);
            }

            Point point = Point.builder()
                    .user(user)
                    .amount(request.getAmount())
                    .remainingAmount(request.getAmount())
                    .reason(request.getReason())
                    .expirationDate(LocalDate.now().plusDays(90)) // 90일 후 만료
                    .status(PointStatus.AVAILABLE)
                    .build();

            Point savedPoint = pointRepository.save(point);

            log.info("포인트 적립 완료 - 사용자: {}, 적립액: {}, 포인트 ID: {}",
                    email, request.getAmount(), savedPoint.getId());

            return PointDto.PointResponse.from(savedPoint);
        } catch (UserNotFoundException | InvalidPointAmountException e) {
            throw e;
        } catch (Exception e) {
            log.error("포인트 적립 중 예상치 못한 오류 발생 - 사용자: {}, 적립액: {}",
                    email, request.getAmount(), e);
            throw new InvalidPointAmountException("포인트 적립 처리 중 오류가 발생했습니다.");
        }
    }

    /**
     * 포인트 사용
     */
    @Transactional
    public PointDto.UsePointResponse usePoint(String email, PointDto.UsePointRequest request) {
        log.info("포인트 사용 시작 - 사용자: {}, 사용액: {}", email, request.getAmount());

        try {
            // 입력값 검증
            validateUsePointRequest(request);

            User user = userQueryService.findByEmail(email);
            if (user == null) {
                throw new UserNotFoundException(email);
            }

            int pointsToUse = request.getAmount();

            // 가용 포인트 총합 확인
            Integer totalAvailable = pointRepository.getTotalAvailablePoints(user);
            if (totalAvailable == null || totalAvailable < pointsToUse) {
                log.warn("포인트 부족 - 사용자: {}, 필요: {}, 보유: {}",
                        email, pointsToUse, totalAvailable != null ? totalAvailable : 0);
                throw new InsufficientPointsException(pointsToUse, totalAvailable != null ? totalAvailable : 0);
            }

            // 만료 임박 포인트부터 사용
            List<Point> availablePoints = pointRepository.findByUserAndStatusOrderByExpirationDateAsc(user, PointStatus.AVAILABLE);
            int remainingToUse = pointsToUse;
            int totalUsed = 0;

            for (Point point : availablePoints) {
                if (remainingToUse <= 0) break;

                Integer usedAmount = point.use(remainingToUse);
                int used = usedAmount != null ? usedAmount : 0;
                remainingToUse -= used;
                totalUsed += used;

                // 포인트 사용 이유 추가
                if (used > 0) {
                    point.setReason(request.getReason());
                    pointRepository.save(point);
                }
            }

            // 사용 후 남은 총 포인트 계산
            Integer remainingTotal = pointRepository.getTotalAvailablePoints(user);
            if (remainingTotal == null) remainingTotal = 0;

            log.info("포인트 사용 완료 - 사용자: {}, 사용액: {}, 남은 포인트: {}",
                    email, totalUsed, remainingTotal);

            return PointDto.UsePointResponse.builder()
                    .usedPoints(totalUsed)
                    .remainingTotalPoints(remainingTotal)
                    .message("포인트가 성공적으로 사용되었습니다.")
                    .build();
        } catch (UserNotFoundException | InvalidPointAmountException | InsufficientPointsException e) {
            throw e;
        } catch (Exception e) {
            log.error("포인트 사용 중 예상치 못한 오류 발생 - 사용자: {}, 사용액: {}",
                    email, request.getAmount(), e);
            throw new InsufficientPointsException("포인트 사용 처리 중 오류가 발생했습니다.");
        }
    }

    /**
     * 만료된 포인트 처리 (스케줄러에서 호출)
     */
    @Transactional
    public int expirePoints() {
        log.info("만료 포인트 처리 시작");

        try {
            List<Point> expiredPoints = pointRepository.findByStatusAndExpirationDateBefore(
                    PointStatus.AVAILABLE, LocalDate.now());

            for (Point point : expiredPoints) {
                point.expire();
            }

            log.info("만료 포인트 처리 완료 - 만료된 포인트 수: {}", expiredPoints.size());
            return expiredPoints.size();
        } catch (Exception e) {
            log.error("만료 포인트 처리 중 오류 발생", e);
            return 0;
        }
    }

    /**
     * 포인트 적립 요청 검증
     */
    private void validateAddPointRequest(PointDto.AddPointRequest request) {
        if (request == null) {
            throw new InvalidPointAmountException("포인트 적립 요청 데이터가 없습니다.");
        }

        if (request.getAmount() <= 0) {
            throw new InvalidPointAmountException(request.getAmount());
        }

        if (request.getAmount() > 1000000) { // 최대 100만 포인트 적립 제한
            throw new InvalidPointAmountException("한 번에 적립할 수 있는 포인트는 최대 1,000,000점입니다.");
        }

        if (request.getReason() == null || request.getReason().trim().isEmpty()) {
            throw new InvalidPointAmountException("포인트 적립 사유를 입력해주세요.");
        }
    }

    /**
     * 포인트 사용 요청 검증
     */
    private void validateUsePointRequest(PointDto.UsePointRequest request) {
        if (request == null) {
            throw new InvalidPointAmountException("포인트 사용 요청 데이터가 없습니다.");
        }

        if (request.getAmount() <= 0) {
            throw new InvalidPointAmountException(request.getAmount());
        }

        if (request.getReason() == null || request.getReason().trim().isEmpty()) {
            throw new InvalidPointAmountException("포인트 사용 사유를 입력해주세요.");
        }
    }
}package com.fream.back.domain.notification.entity;

public enum NotificationType {

    // SHOPPING 카테고리 알림 유형
    TRADE(NotificationCategory.SHOPPING, "거래 관련 알림"),
    BID(NotificationCategory.SHOPPING, "입찰 관련 알림"),
    STORAGE(NotificationCategory.SHOPPING, "보관 관련 알림"),
    FAVORITE(NotificationCategory.SHOPPING, "관심 상품 관련 알림"),
    BENEFIT(NotificationCategory.SHOPPING, "혜택 관련 알림"),
    ANNOUNCEMENT(NotificationCategory.SHOPPING, "공지사항 알림"),
    REFUND(NotificationCategory.SHOPPING, "환불 관련 알림"), // 추가: 환불 알림 유형

    // STYLE 카테고리 알림 유형
    LIKE(NotificationCategory.STYLE, "좋아요 관련 알림"),
    COMMENT(NotificationCategory.STYLE, "댓글 관련 알림"),
    FOLLOW(NotificationCategory.STYLE, "팔로우 관련 알림");

    private final NotificationCategory category;
    private final String description;

    NotificationType(NotificationCategory category, String description) {
        this.category = category;
        this.description = description;
    }

    public NotificationCategory getCategory() {
        return category;
    }

    public String getDescription() {
        return description;
    }

    /**
     * 특정 카테고리에 속하는 모든 알림 유형을 반환
     *
     * @param category 검색할 카테고리
     * @return 카테고리에 속하는 알림 유형 배열
     */
    public static NotificationType[] getTypesByCategory(NotificationCategory category) {
        if (category == null) {
            return values();
        }

        return java.util.Arrays.stream(values())
                .filter(type -> type.getCategory() == category)
                .toArray(NotificationType[]::new);
    }
}package com.fream.back.domain.notification.entity;

public enum NotificationCategory {

    SHOPPING("쇼핑 관련 알림"),
    STYLE("스타일 관련 알림");

    private final String description;

    NotificationCategory(String description) {
        this.description = description;
    }

    public String getDescription() {
        return description;
    }
}package com.fream.back.domain.shipment.config;

import com.fream.back.domain.notification.service.command.NotificationCommandService;
import com.fream.back.domain.shipment.entity.OrderShipment;
import com.fream.back.domain.shipment.entity.ShipmentStatus;
import com.fream.back.domain.shipment.exception.ShipmentErrorCode;
import com.fream.back.domain.shipment.exception.ShipmentException;
import com.fream.back.domain.shipment.service.command.OrderShipmentCommandService;
import com.fream.back.global.utils.PlaywrightBrowserManager;
import com.microsoft.playwright.Page;
import lombok.extern.slf4j.Slf4j;
import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.select.Elements;
import org.springframework.batch.item.ItemProcessor;

/**
 * 배송 상태 배치 처리를 위한 ItemProcessor
 * 주문 배송 상태를 조회하고 처리합니다.
 */
@Slf4j
public class ShipmentItemProcessor implements ItemProcessor<OrderShipment, OrderShipment> {

    private final PlaywrightBrowserManager browserManager;
    private final NotificationCommandService notificationService;
    private final OrderShipmentCommandService orderService;

    private static final String TRACKING_URL_PREFIX = "https://trace.cjlogistics.com/next/tracking.html?wblNo=";
    private static final String STATUS_SELECTOR = "tbody#statusDetail tr";
    private static final int TIMEOUT_MS = 30000; // 30초

    /**
     * 배송 상태 처리기 생성자
     *
     * @param browserManager Playwright 브라우저 관리자
     * @param notificationService 알림 서비스
     * @param orderService 주문 서비스
     */
    public ShipmentItemProcessor(
            PlaywrightBrowserManager browserManager,
            NotificationCommandService notificationService,
            OrderShipmentCommandService orderService
    ) {
        this.browserManager = browserManager;
        this.notificationService = notificationService;
        this.orderService = orderService;
    }

    /**
     * 주문 배송의 상태를 외부 서비스를 통해 조회하고 업데이트합니다.
     *
     * @param orderShipment 처리할 배송 정보
     * @return 업데이트된 배송 정보
     * @throws Exception 처리 중 오류 발생 시
     */
    @Override
    public OrderShipment process(OrderShipment orderShipment) throws Exception {
        String trackingNumber = orderShipment.getTrackingNumber();
        Long shipmentId = orderShipment.getId();

        if (trackingNumber == null || trackingNumber.isBlank()) {
            log.warn("유효하지 않은 운송장 번호: shipmentId={}", shipmentId);
            throw new ShipmentException(ShipmentErrorCode.TRACKING_NUMBER_INVALID);
        }

        log.info("배송 상태 처리 시작: shipmentId={}, trackingNumber={}, currentStatus={}",
                shipmentId, trackingNumber, orderShipment.getStatus());

        Page page = null;
        try {
            // browserManager를 통해 페이지 생성
            page = browserManager.newPage();
            if (page == null) {
                throw new ShipmentException(ShipmentErrorCode.BROWSER_INITIALIZATION_ERROR);
            }

            // 타임아웃 설정
            page.setDefaultTimeout(TIMEOUT_MS);

            // 배송 추적 URL로 이동
            String url = TRACKING_URL_PREFIX + trackingNumber;
            log.debug("배송 조회 페이지로 이동: {}", url);
            page.navigate(url);

            // 배송 상태 테이블 로드 대기
            log.debug("배송 상태 테이블 로드 대기");
            page.waitForSelector(STATUS_SELECTOR);

            // 최종 HTML 가져오기
            String renderedHtml = page.content();
            log.debug("페이지 HTML 로드 완료 (길이: {})", renderedHtml.length());

            // HTML 파싱하여 배송 상태 추출
            String statusText = parseStatusFromHtml(renderedHtml, trackingNumber);
            ShipmentStatus newStatus = mapToShipmentStatus(statusText);

            log.debug("배송 상태 조회 결과: shipmentId={}, statusText={}, mappedStatus={}",
                    shipmentId, statusText, newStatus);

            // 현재 상태와 동일한 경우 중복 처리 방지
            if (orderShipment.getStatus() == newStatus) {
                log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
                        shipmentId, newStatus);
                return orderShipment;
            }

            // 상태에 따른 처리
            if (newStatus == ShipmentStatus.DELIVERED) {
                log.info("배송 완료 처리: shipmentId={}, orderId={}",
                        shipmentId, orderShipment.getOrder().getId());

                // 배송 상태 업데이트
                orderShipment.updateStatus(ShipmentStatus.DELIVERED);

                // 주문 완료 처리 및 알림
                orderService.completeOrder(orderShipment.getOrder().getId());
                notificationService.notifyShipmentCompleted(orderShipment.getOrder());

            } else if (newStatus == ShipmentStatus.OUT_FOR_DELIVERY) {
                log.info("배송 출발 처리: shipmentId={}", shipmentId);
                orderShipment.updateStatus(ShipmentStatus.OUT_FOR_DELIVERY);

            } else {
                log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
                orderShipment.updateStatus(ShipmentStatus.IN_TRANSIT);
            }

            log.info("배송 상태 처리 완료: shipmentId={}, newStatus={}",
                    shipmentId, orderShipment.getStatus());

            return orderShipment;

        } catch (Exception e) {
            log.error("배송 상태 처리 중 오류 발생: shipmentId={}, trackingNumber={}, error={}",
                    shipmentId, trackingNumber, e.getMessage(), e);

            // ShipmentException 타입이 아닌 경우 래핑
            if (!(e instanceof ShipmentException)) {
                throw new ShipmentException(
                        ShipmentErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
                        "배송 상태 조회 중 오류 발생: " + e.getMessage(),
                        e
                );
            }
            throw e;
        } finally {
            // 페이지 리소스 해제
            if (page != null) {
                try {
                    page.close();
                    log.debug("페이지 리소스 해제 완료");
                } catch (Exception e) {
                    log.warn("페이지 닫기 실패: {}", e.getMessage());
                }
            }
        }
    }

    /**
     * HTML에서 배송 상태를 파싱합니다.
     *
     * @param html 파싱할 HTML 문자열
     * @param trackingNumber 로깅용 운송장 번호
     * @return 배송 상태 문자열
     * @throws ShipmentException 파싱 실패 시 발생
     */
    private String parseStatusFromHtml(String html, String trackingNumber) {
        try {
            Document doc = Jsoup.parse(html);
            Elements rows = doc.select(STATUS_SELECTOR);

            if (rows.isEmpty()) {
                log.warn("배송 상태 테이블이 비어 있음: 운송장={}", trackingNumber);
                throw new ShipmentException(
                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
                        "배송 정보가 없습니다. 운송장 번호를 확인해주세요: " + trackingNumber
                );
            }

            // 마지막 행(최신 상태)의 5번째 컬럼 선택
            String statusText = rows.last().select("td").get(4).text().trim();

            if (statusText.isEmpty()) {
                log.warn("배송 상태 텍스트가 비어 있음: 운송장={}", trackingNumber);
                throw new ShipmentException(
                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
                        "배송 상태 정보를 찾을 수 없습니다."
                );
            }

            return statusText;

        } catch (IndexOutOfBoundsException e) {
            log.error("HTML 파싱 중 인덱스 오류: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
            throw new ShipmentException(
                    ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
                    "배송 상태 정보 파싱 실패: 예상한 형식과 다릅니다.",
                    e
            );
        } catch (Exception e) {
            if (e instanceof ShipmentException) {
                throw (ShipmentException) e;
            }

            log.error("HTML 파싱 중 오류 발생: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
            throw new ShipmentException(
                    ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
                    "배송 상태 정보 파싱 실패: " + e.getMessage(),
                    e
            );
        }
    }

    /**
     * 배송사 상태 텍스트를 내부 ShipmentStatus로 매핑합니다.
     *
     * @param statusText 배송사 상태 텍스트
     * @return 매핑된 ShipmentStatus
     */
    private ShipmentStatus mapToShipmentStatus(String statusText) {
        return switch (statusText) {
            case "배송완료" -> ShipmentStatus.DELIVERED;
            case "배송출발" -> ShipmentStatus.OUT_FOR_DELIVERY;
            default -> ShipmentStatus.IN_TRANSIT;
        };
    }
}

