/**
 * 배송 완료된 주문의 구매자에게 주문 총액의 1%를 포인트로 적립하고 혜택 알림을 보냅니다.
 * 주문 상태를 COMPLETED로 바꾼 직후에만 호출되므로 주문당 한 번만 적립됩니다.
 *
 * @param order 배송 완료 처리된 주문
 */
private void grantPurchaseReward(Order order) {
    int reward = order.getTotalAmount() / 100; // 1% 적립, 1포인트 미만은 버림
    if (reward <= 0) {
        log.debug("구매 적립 포인트 없음: orderId={}, totalAmount={}", order.getId(), order.getTotalAmount());
        return;
    }

    User buyer = order.getUser();
    pointCommandService.earnPurchasePoint(buyer, reward, "구매 적립 (주문 ID: " + order.getId() + ")");
    notificationCommandService.createNotification(
            buyer.getId(),
            NotificationCategory.SHOPPING,
            NotificationType.BENEFIT,
            String.format("구매 혜택으로 %,dP가 적립되었습니다. 주문 ID: %d", reward, order.getId())
    );

    log.info("구매 적립 완료: userId={}, orderId={}, point={}", buyer.getId(), order.getId(), reward);
}

